def _mutate(data):
    nonlocal result
    if "permissions" not in data:
        return None
    tools = data["permissions"].get("tools")
    if not isinstance(tools, dict):
        return None
    key_to_drop = None
    for k in tools:
        if str(k).strip() == name:
            key_to_drop = k
            break
    if key_to_drop is None:
        return None
    new_tools = {k: v for k, v in tools.items() if k != key_to_drop}
    data["permissions"]["tools"] = new_tools
    result = True
    return data

